pragma solidity 0.6.10;
pragma experimental ABIEncoderV2;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { MarketParams, IMorpho } from "../../../interfaces/external/morpho/IMorpho.sol";
import { ISetToken } from "../../../interfaces/ISetToken.sol";

/**
 * @title Morpho
 * @author Index Coop
 * 
 * Collection of helper functions for interacting with Morpho Blue
 */
library Morpho {
    /* ============ External ============ */

    function getSupplyCollateralCalldata(
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _assets,
        address _onBehalfOf,
        bytes memory _data
    )
        public
        pure
        returns (address, uint256, bytes memory)
    {
        bytes memory callData = abi.encodeWithSignature(
            "supplyCollateral((address,address,address,address,uint256),uint256,address,bytes)", 
            _marketParams, 
            _assets, 
            _onBehalfOf,
            _data
        );

        return (address(_morpho), 0, callData);
    }

    function invokeSupplyCollateral(
        ISetToken _setToken,
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _amountNotional
    )
        external
    {
        bytes memory data = bytes("");
        ( , , bytes memory supplyCollateralCalldata) = getSupplyCollateralCalldata(
            _morpho,
            _marketParams,
            _amountNotional, 
            address(_setToken), 
            data
        );

        _setToken.invoke(address(_morpho), 0, supplyCollateralCalldata);
    }

    function getBorrowCalldata(
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _assets,
        uint256 _shares,
        address _onBehalfOf,
        address _receiver
    )
        public
        pure
        returns (address, uint256, bytes memory)
    {
        bytes memory callData = abi.encodeWithSignature(
            "borrow((address,address,address,address,uint256),uint256,uint256,address,address)",
            _marketParams, 
            _assets, 
            _shares, 
            _onBehalfOf,
            _receiver
        );

        return (address(_morpho), 0, callData);
    }

    function invokeBorrow(
        ISetToken _setToken,
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _amountNotional
    )
        external
    {
        ( , , bytes memory borrowCalldata) = getBorrowCalldata(
            _morpho,
            _marketParams,
            _amountNotional, 
            0,
            address(_setToken), 
            address(_setToken)
        );

        _setToken.invoke(address(_morpho), 0, borrowCalldata);
    }

    function getWithdrawCollateralCalldata(
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _assets,
        address _onBehalfOf,
        address _receiver
    )
        public
        pure
        returns (address, uint256, bytes memory)
    {
        bytes memory callData = abi.encodeWithSignature(
            "withdrawCollateral((address,address,address,address,uint256),uint256,address,address)",
            _marketParams, 
            _assets, 
            _onBehalfOf,
            _receiver
        );

        return (address(_morpho), 0, callData);
    }

    function invokeWithdrawCollateral(
        ISetToken _setToken,
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _amountNotional
    )
        external
    {
        ( , , bytes memory withdrawCollateralCalldata) = getWithdrawCollateralCalldata(
            _morpho,
            _marketParams,
            _amountNotional, 
            address(_setToken), 
            address(_setToken)
        );

        _setToken.invoke(address(_morpho), 0, withdrawCollateralCalldata);
    }


     function getRepayCalldata(
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _assets,
        uint256 _shares,
        address _onBehalfOf
    )
        public
        pure
        returns (address, uint256, bytes memory)
    {
        bytes memory data = bytes("");
        bytes memory callData = abi.encodeWithSignature(
            "repay((address,address,address,address,uint256),uint256,uint256,address,bytes)",
            _marketParams, 
            _assets, 
            _shares, 
            _onBehalfOf,
            data
        );

        return (address(_morpho), 0, callData);
    }

    function invokeRepay(
        ISetToken _setToken,
        IMorpho _morpho,
        MarketParams memory _marketParams,
        uint256 _assets,
        uint256 _shares
    )
        external
    {
        ( , , bytes memory repayCalldata) = getRepayCalldata(
            _morpho,
            _marketParams,
            _assets, 
            _shares,
            address(_setToken)
        );

        _setToken.invoke(address(_morpho), 0, repayCalldata);
    }


}

